import {
  CJK_LANGS,
  CJK_OVERRIDES,
  COLOR_TOKENS,
  DERIVED_TOKENS,
  SHADOW_TOKENS,
  STATIC_TOKEN_GROUPS,
  type ThemeName,
} from './tokens';

export const TOKENS_CSS_GENERATED_HEADER =
  '/* GENERATED by packages/fantay-tokens/scripts/generate-css.ts — do not edit. Run: pnpm --filter @fantay/tokens generate */';
export const TOKENS_CSS_LICENSE_HEADER =
  '/* SPDX-License-Identifier: AGPL-3.0-only — values derived from Doop src/styles.css @ d261a85d3f9d87ac0653bb8512915f4e5bdff2b9 (AGPL-3.0) and Radix Colors violet (MIT, Copyright (c) 2021 Radix). */';

const INDENT = '  ';

function declaration(name: string, value: string): string {
  return `${INDENT}--${name}: ${value};`;
}

function themeDeclarations(theme: ThemeName): string[] {
  return [
    `${INDENT}color-scheme: ${theme};`,
    `${INDENT}/* colours */`,
    ...Object.entries(COLOR_TOKENS).map(([name, value]) => declaration(name, value[theme])),
    `${INDENT}/* shadows */`,
    ...Object.entries(SHADOW_TOKENS).map(([name, value]) => declaration(name, value[theme])),
    `${INDENT}/* derived: re-resolve on every themed element */`,
    ...Object.entries(DERIVED_TOKENS).map(([name, value]) => declaration(name, value)),
  ];
}

/**
 * The committed `packages/fantay-tokens/tokens.css`, rendered from the token tables.
 * Pure and deterministic: 2-space indent, declarations in table order, one trailing newline.
 */
export function renderTokensCss(): string {
  const lines: string[] = [TOKENS_CSS_GENERATED_HEADER, TOKENS_CSS_LICENSE_HEADER, ':root {'];
  for (const group of STATIC_TOKEN_GROUPS) {
    lines.push(`${INDENT}/* ${group.label} */`);
    for (const [name, value] of Object.entries(group.tokens)) lines.push(declaration(name, value));
  }
  lines.push('}');

  lines.push(...CJK_LANGS.map((lang, index) => `:root:lang(${lang})${index === CJK_LANGS.length - 1 ? ' {' : ','}`));
  lines.push(`${INDENT}/* CJK labels never below 12px (D1) */`);
  for (const [name, value] of Object.entries(CJK_OVERRIDES)) lines.push(declaration(name, value));
  lines.push('}');

  lines.push(':root,', '[data-theme="light"] {', ...themeDeclarations('light'), '}');
  lines.push('[data-theme="dark"] {', ...themeDeclarations('dark'), '}');
  return `${lines.join('\n')}\n`;
}
